fn count_digits(text: &Vec<char>) -> usize {
    text.iter()
        .filter(|&&c| c >= '0' && c <= '9')
        .count()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let v: Vec<char> = Vec::new();
        assert_eq!(count_digits(&v), 0);
    }

    #[test]
    fn test_no_digits() {
        let v: Vec<char> = "abcXYZ!@#".chars().collect();
        assert_eq!(count_digits(&v), 0);
    }

    #[test]
    fn test_all_digits() {
        let v: Vec<char> = "0123456789".chars().collect();
        assert_eq!(count_digits(&v), 10);
    }

    #[test]
    fn test_mixed() {
        let v: Vec<char> = "a1b2c3!45d6".chars().collect();
        // digits are 1,2,3,4,5,6 => 6
        assert_eq!(count_digits(&v), 6);
    }

    #[test]
    fn test_unicode_non_ascii_digits() {
        // These are Unicode digits, not ASCII
        let v: Vec<char> = vec!['①', '2', '٣', '4'];
        // Only '2' and '4' are ASCII 0-9
        assert_eq!(count_digits(&v), 2);
    }
}